async listarClientes(restaurantId: number, filtros: { busca?: string; limite?: number }) {
  // Busca IDs dos clientes vinculados a este restaurante
  const { data: crRows, error: crErr } = await this.supabase.client
    .from('customer_restaurants')
    .select('customer_id')
    .eq('restaurant_id', restaurantId);

  if (crErr) throw crErr;
  const customerIds = (crRows ?? []).map((r) => r.customer_id);
  if (customerIds.length === 0) return { clientes: [], total: 0 };

  // Busca dados dos clientes com filtro opcional
  let q = this.supabase.client
    .from('customers')
    .select('id, name, email, phone_e164, notes, user_id, created_at')
    .in('id', customerIds)
    .order('name');

  if (filtros.busca) {
    q = q.or(`name.ilike.%${filtros.busca}%,email.ilike.%${filtros.busca}%,phone_e164.ilike.%${filtros.busca}%`);
  }
  if (filtros.limite) q = q.limit(filtros.limite);

  const { data: clientes, error: cErr } = await q;
  if (cErr) throw cErr;

  if (!clientes?.length) return { clientes: [], total: 0 };

  // Busca estatísticas de pedidos por cliente neste restaurante
  const ids = clientes.map((c) => c.id);
  const { data: pedidos } = await this.supabase.client
    .from('orders')
    .select('customer_id, total, created_at')
    .eq('restaurant_id', restaurantId)
    .in('customer_id', ids)
    .neq('status', 'canceled');

  const statsMap: Record<number, { count: number; total: number; ultimo: string | null }> = {};
  for (const p of pedidos ?? []) {
    if (!statsMap[p.customer_id]) statsMap[p.customer_id] = { count: 0, total: 0, ultimo: null };
    statsMap[p.customer_id].count++;
    statsMap[p.customer_id].total += parseFloat(p.total);
    if (!statsMap[p.customer_id].ultimo || p.created_at > (statsMap[p.customer_id].ultimo as string)) {
      statsMap[p.customer_id].ultimo = p.created_at;
    }
  }

  const result = clientes.map((c) => ({
    ...c,
    pedidos_count: statsMap[c.id]?.count ?? 0,
    total_gasto: statsMap[c.id]?.total ?? 0,
    ultimo_pedido: statsMap[c.id]?.ultimo ?? null,
  }));

  return { clientes: result, total: result.length };
}

async criarCliente(
  restaurantId: number,
  body: { name: string; email?: string; phone_e164?: string; notes?: string },
) {
  const { data, error } = await this.supabase.client
    .from('customers')
    .insert({
      name: body.name,
      email: body.email ?? null,
      phone_e164: body.phone_e164 ?? null,
      notes: body.notes ?? null,
    })
    .select()
    .single();

  if (error) throw error;

  // Vincula ao restaurante
  await this.supabase.client
    .from('customer_restaurants')
    .insert({ customer_id: data.id, restaurant_id: restaurantId })
    .throwOnError();

  return data;
}

async atualizarCliente(
  clienteId: number,
  restaurantId: number,
  body: Partial<{ name: string; email: string; phone_e164: string; notes: string }>,
) {
  // Verifica vínculo com o restaurante
  const { data: cr } = await this.supabase.client
    .from('customer_restaurants')
    .select('customer_id')
    .eq('customer_id', clienteId)
    .eq('restaurant_id', restaurantId)
    .maybeSingle();

  if (!cr) throw new NotFoundException('Cliente não encontrado neste restaurante');

  // body é Partial<{...}> — tipo TS puro, não classe validada — nunca
  // repassar cru pro .update() (mesmo padrão de fix já usado em B2/B7/B10).
  const campos: Record<string, any> = { updated_at: new Date().toISOString() };
  if (body.name !== undefined) campos.name = body.name;
  if (body.email !== undefined) campos.email = body.email;
  if (body.phone_e164 !== undefined) campos.phone_e164 = body.phone_e164;
  if (body.notes !== undefined) campos.notes = body.notes;

  const { data, error } = await this.supabase.client
    .from('customers')
    .update(campos)
    .eq('id', clienteId)
    .select()
    .single();

  if (error) throw error;
  return data;

-- Relacionamento N:N entre clientes e restaurantes
-- Um cliente pode pedir em vários restaurantes; cada restaurante vê só seus clientes

CREATE TABLE IF NOT EXISTS public.customer_restaurants (
  customer_id  BIGINT NOT NULL REFERENCES public.customers(id)   ON DELETE CASCADE,
  restaurant_id BIGINT NOT NULL REFERENCES public.restaurants(id) ON DELETE CASCADE,
  created_at   TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  PRIMARY KEY (customer_id, restaurant_id)
);

CREATE INDEX IF NOT EXISTS idx_cr_restaurant ON public.customer_restaurants(restaurant_id);
CREATE INDEX IF NOT EXISTS idx_cr_customer   ON public.customer_restaurants(customer_id);

ALTER TABLE public.customer_restaurants ENABLE ROW LEVEL SECURITY;

-- Dono do restaurante vê seus clientes
CREATE POLICY "owner_ver_cr" ON public.customer_restaurants
  FOR SELECT USING (
    restaurant_id IN (
      SELECT id FROM public.restaurants WHERE user_id = auth.uid()
    )
  );

-- Popula automaticamente ao criar pedido (quando customer_id existe)
CREATE OR REPLACE FUNCTION public.fn_link_customer_restaurant()
RETURNS TRIGGER AS $$
BEGIN
  IF NEW.customer_id IS NOT NULL THEN
    INSERT INTO public.customer_restaurants (customer_id, restaurant_id)
    VALUES (NEW.customer_id, NEW.restaurant_id)
    ON CONFLICT (customer_id, restaurant_id) DO NOTHING;
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

DROP TRIGGER IF EXISTS trg_link_customer_restaurant ON public.orders;
CREATE TRIGGER trg_link_customer_restaurant
  AFTER INSERT ON public.orders
  FOR EACH ROW EXECUTE FUNCTION public.fn_link_customer_restaurant();

-- Backfill: vincular clientes que já têm pedidos
INSERT INTO public.customer_restaurants (customer_id, restaurant_id)
SELECT DISTINCT customer_id, restaurant_id
FROM   public.orders
WHERE  customer_id IS NOT NULL
ON CONFLICT DO NOTHING;

