28	
29	  // Últimos 8 dígitos bastam pra casar apesar de variação de formato (com/sem
30	  // DDI, com/sem 9º dígito) — evita exigir telefone digitado igual byte a byte.
31	  private normalizarTelefone(tel: string): string {
32	    return (tel || '').replace(/\D/g, '');
33	  }
34	
35	  // Busca cliente já vinculado a este restaurante pelo telefone — usada tanto na
36	  // digitação (autocomplete no app do garçom) quanto pra resolver o customer_id
37	  // ao abrir a comanda, unificando o cadastro do balcão/comanda com o do delivery.
38	  async buscarClientePorTelefone(restaurantId: number, telefone: string) {
39	    const digitos = this.normalizarTelefone(telefone);
40	    if (digitos.length < 8) return null;
41	    const sufixo = digitos.slice(-8);
42	
43	    const { data: crRows } = await this.supabase.client
44	      .from('customer_restaurants')
45	      .select('customer_id')
46	      .eq('restaurant_id', restaurantId);
47	    const ids = (crRows ?? []).map((r) => r.customer_id);
48	    if (!ids.length) return null;
49	
50	    const { data: candidatos } = await this.supabase.client
51	      .from('customers')
52	      .select('id, name, phone_e164')
53	      .in('id', ids)
54	      .not('phone_e164', 'is', null)
55	      .ilike('phone_e164', `%${sufixo}%`);
56	
57	    const match = (candidatos ?? []).find((c) => this.normalizarTelefone(c.phone_e164).endsWith(sufixo));
58	    return match ? { id: match.id, name: match.name } : null;
59	  }
60	
61	  // Resolve o customer_id da comanda: reaproveita cliente já cadastrado (delivery
62	  // ou comanda anterior) pelo telefone, ou cria um novo com nome/telefone que o
63	  // garçom já é obrigado a digitar — sem passo extra pra ele.
64	  private async resolverOuCriarClienteComanda(restaurantId: number, nome: string, telefone: string): Promise<number | null> {
65	    const existente = await this.buscarClientePorTelefone(restaurantId, telefone);
66	    if (existente) return existente.id;
67	
68	    const digitos = this.normalizarTelefone(telefone);
69	    if (digitos.length < 8) return null;
70	
71	    const { data: novoCliente, error } = await this.supabase.client
72	      .from('customers')
73	      .insert({ name: nome, phone_e164: telefone })
74	      .select('id')
75	      .single();
76	    if (error || !novoCliente) return null;
77	
78	    await this.supabase.client
79	      .from('customer_restaurants')
80	      .insert({ customer_id: novoCliente.id, restaurant_id: restaurantId })
81	      .throwOnError();
82	
83	    return novoCliente.id;
84	  }
