86	  async mesas(restaurantId: number) {
87	    const { data: mesas, error } = await this.supabase.client
88	      .from('mesas')
89	      .select('id, numero, nome, status')
90	      .eq('restaurant_id', restaurantId)
91	      .order('numero', { ascending: true });
92	    if (error) throw error;
93	
94	    // Precisa saber de quem é a comanda em cada mesa ocupada — o garçom só pode
95	    // clicar/entrar se a comanda for dele (ver garcom-portal, grid de mesas).
96	    const { data: comandas } = await this.supabase.client
97	      .from('orders')
98	      .select('id, mesa_id, garcom_id, cliente_mesa_nome, total, garcons(nome), aberto_por_nome, conferencia_solicitada_em, conferencia_vista_garcom_em')
99	      .eq('restaurant_id', restaurantId)
100	      .eq('canal', 'presencial')
101	      .in('status', ['aberta', 'fechada_garcom'])
102	      .not('mesa_id', 'is', null);
103	
104	    const comandaPorMesa = new Map((comandas ?? []).map((c: any) => [c.mesa_id, c]));
105	
106	    return (mesas ?? []).map((m: any) => ({ ...m, comanda: comandaPorMesa.get(m.id) ?? null }));
107	  }
108	
109	  // Acompanhamento público via QR (ideia 13) — sem auth, só o essencial pro cliente da mesa.
110	  async acompanharPorToken(token: string) {
111	    const { data: comanda } = await this.supabase.client
112	      .from('orders')
113	      .select('id, restaurant_id, status, numero_comanda, desconto_valor, acrescimo_valor, gorjeta_valor, conferencia_solicitada_em, mesas(numero, nome), restaurants(name, gorjeta_percentual)')
114	      .eq('tracking_token', token)
115	      .eq('canal', 'presencial')
116	      .maybeSingle();
117	    if (!comanda) throw new NotFoundException('Comanda não encontrada');
118	
119	    const { data: itens } = await this.supabase.client
120	      .from('order_items')
121	      .select('id, quantity, unit_price, status, enviado_em, preparando_em, products(name)')
122	      .eq('order_id', comanda.id)
123	      .order('id', { ascending: true });
124	
125	    // Mesma fila e mesmas médias que o garçom vê — o cliente não precisa perguntar
126	    // "quantos faltam antes do meu" ou "quanto tempo em média demora".
127	    const fila = await this.filaCozinha((comanda as any).restaurant_id);
128	    const aguardandoIds = fila.itens.filter((i) => i.status === 'enviado').map((i) => i.item_id);
129	    const preparandoIds = fila.itens.filter((i) => i.status === 'preparando').map((i) => i.item_id);
130	
131	    // Conta pra conferência visual — mesmos números que o caixa usa pra fechar (ver
132	    // saldoDevedor), o cliente confere sem precisar perguntar "quanto já deu".
133	    const saldo = await this.saldoDevedor(comanda.id);
134	    const percentualGorjeta = (comanda as any).restaurants?.gorjeta_percentual ?? 0;
135	
136	    const { data: pagamentos } = await this.supabase.client
137	      .from('comanda_pagamentos')
138	      .select('valor, forma_pagamento, criado_em, taxa_cartao_valor')
139	      .eq('order_id', comanda.id)
140	      .order('criado_em', { ascending: true });
141	    const taxaCartaoTotal = (pagamentos ?? []).reduce((acc: number, p: any) => acc + (p.taxa_cartao_valor ?? 0), 0);
142	
143	    // gorjeta_valor só é gravado quando a comanda é paga (garçom/caixa escolhe o valor
144	    // na hora) — enquanto a comanda ainda está aberta o cliente não vê nenhuma gorjeta
145	    // no Total/Falta pagar, mesmo o restaurante tendo um percentual sugerido configurado.
146	    // Estimativa: calcula em cima do percentual pra já aparecer no acompanhamento antes
147	    // do pagamento; quando pago, usa o valor real cobrado (não recalcula).
148	    const gorjetaJaDefinida = (comanda as any).gorjeta_valor !== null && (comanda as any).gorjeta_valor !== undefined;
149	    const gorjetaEstimativa = !gorjetaJaDefinida && comanda.status !== 'paga' && percentualGorjeta > 0;
150	    let gorjetaValor = (comanda as any).gorjeta_valor ?? 0;
151	    let totalComGorjeta = saldo.total;
152	    let saldoComGorjeta = saldo.saldo;
153	    if (gorjetaEstimativa) {
154	      const baseCalculo = saldo.subtotal - ((comanda as any).desconto_valor ?? 0) + ((comanda as any).acrescimo_valor ?? 0);
155	      gorjetaValor = parseFloat(((baseCalculo * percentualGorjeta) / 100).toFixed(2));
156	      totalComGorjeta = parseFloat((saldo.total + gorjetaValor).toFixed(2));
157	      saldoComGorjeta = parseFloat((saldo.saldo + gorjetaValor).toFixed(2));
158	    }
159	
160	    return {
161	      restaurante: (comanda as any).restaurants?.name,
162	      mesa: (comanda as any).mesas ? `Mesa ${(comanda as any).mesas.numero}` : null,
163	      numero_comanda: (comanda as any).numero_comanda,
164	      status: comanda.status,
165	      conferencia_solicitada_em: (comanda as any).conferencia_solicitada_em,
166	      tempoMedioEsperaSegundos: fila.tempoMedioEsperaSegundos,
167	      tempoMedioPreparoSegundos: fila.tempoMedioPreparoSegundos,
168	      tempoMedioGeralSegundos: fila.tempoMedioGeralSegundos,
169	      subtotal: saldo.subtotal,
170	      desconto: (comanda as any).desconto_valor ?? 0,
171	      acrescimo: (comanda as any).acrescimo_valor ?? 0,
172	      gorjeta_percentual: percentualGorjeta,
173	      gorjeta: gorjetaValor,
174	      gorjeta_estimativa: gorjetaEstimativa,
175	      total: totalComGorjeta,
176	      total_pago: saldo.total_pago,
177	      taxa_cartao_total: parseFloat(taxaCartaoTotal.toFixed(2)),
178	      saldo: saldoComGorjeta,
179	      pagamentos: (pagamentos ?? []).map((p: any) => ({
180	        valor: p.valor,
181	        forma_pagamento: p.forma_pagamento,
182	        criado_em: p.criado_em,
183	        taxa_cartao_valor: p.taxa_cartao_valor ?? 0,
184	      })),
185	      itens: (itens ?? []).map((i: any) => ({
186	        quantity: i.quantity,
187	        unit_price: i.unit_price,
188	        subtotal: parseFloat((i.quantity * i.unit_price).toFixed(2)),
189	        status: i.status,
190	        enviado_em: i.enviado_em,
191	        preparando_em: i.preparando_em,
192	        product_name: i.products?.name,
193	        posicao_fila:
194	          i.status === 'enviado' ? aguardandoIds.indexOf(i.id) + 1
195	          : i.status === 'preparando' ? preparandoIds.indexOf(i.id) + 1
196	          : null,
197	      })),
198	    };
199	  }
