201	  async produtos(restaurantId: number) {
202	    const { data, error } = await this.supabase.client
203	      .from('products')
204	      .select('id, name, price, image_url, category_id, quantidade_estoque, categories(name)')
205	      .eq('restaurant_id', restaurantId)
206	      .eq('is_active', true)
207	      .gt('quantidade_estoque', 0)
208	      .order('name', { ascending: true });
209	    if (error) throw error;
210	    return (data ?? []).map((p: any) => ({ ...p, category_name: p.categories?.name ?? 'Outros' }));
211	  }
212	
213	  // Combo é entidade separada de products (ver CombosService) — lista à parte pro
214	  // garçom oferecer junto do cardápio normal na comanda. Some da lista se faltar
215	  // estoque de qualquer produto que o compõe (mesma regra do produto avulso).
