221	  private async garantirComandaDoGarcom(comandaId: number, garcomId: number) {
222	    const { data } = await this.supabase.client
223	      .from('orders')
224	      .select('id, status, restaurant_id, mesa_id, garcom_id, numero_comanda, cliente_mesa_nome, cliente_mesa_telefone, tracking_token, desconto_valor, acrescimo_valor, gorjeta_valor, sem_gorjeta, mesas(numero, nome, auto_atendimento_token), garcons(nome)')
225	      .eq('id', comandaId)
226	      .eq('canal', 'presencial')
227	      .maybeSingle();
228	    if (!data) throw new NotFoundException('Comanda não encontrada');
229	    if (data.garcom_id !== garcomId) throw new ForbiddenException('Comanda não pertence a este garçom');
230	    return data;
231	  }
