233	  // Débito/crédito acrescentam a taxa configurada em Config > "Taxa do cartão" — o valor
234	  // cobrado do cliente aumenta, PIX e dinheiro não são afetados. Compartilhado entre o
235	  // fechamento do caixa (SalaoPdvService) e o pagamento parcial feito pelo garçom.
236	  async calcularTaxaCartao(restaurantId: number, valor: number, formaPagamento: string): Promise<number> {
237	    if (formaPagamento !== 'credit_card' && formaPagamento !== 'debit_card') return 0;
238	    if (!(valor > 0)) return 0;
239	    const { data: restaurante } = await this.supabase.client
240	      .from('restaurants')
241	      .select('taxa_cartao_percentual')
242	      .eq('id', restaurantId)
243	      .maybeSingle();
244	    const percentual = restaurante?.taxa_cartao_percentual ?? 0;
245	    return parseFloat(((valor * percentual) / 100).toFixed(2));
246	  }
247	
248	  // Saldo devedor considerando pagamentos parciais já registrados (garçom ou caixa).
249	  // Total = produtos - desconto + acréscimo manual + gorjeta + taxa de cartão já
250	  // aplicada nos pagamentos feitos — pra "falta pagar" bater com a conta real, não
251	  // só o valor dos produtos (gorjeta/taxa de cartão eram ignoradas antes).
252	  async saldoDevedor(comandaId: number) {
253	    const { data: itens } = await this.supabase.client.from('order_items').select('quantity, unit_price').eq('order_id', comandaId);
254	    const { data: comanda } = await this.supabase.client
255	      .from('orders')
256	      .select('desconto_valor, acrescimo_valor, gorjeta_valor')
257	      .eq('id', comandaId)
258	      .maybeSingle();
259	    const { data: pagamentos } = await this.supabase.client.from('comanda_pagamentos').select('valor, taxa_cartao_valor').eq('order_id', comandaId);
260	
261	    const subtotal = (itens ?? []).reduce((acc: number, i: any) => acc + i.quantity * i.unit_price, 0);
262	    const totalTaxaCartao = (pagamentos ?? []).reduce((acc: number, p: any) => acc + (p.taxa_cartao_valor ?? 0), 0);
263	    const totalFinal = subtotal - (comanda?.desconto_valor ?? 0) + (comanda?.acrescimo_valor ?? 0) + (comanda?.gorjeta_valor ?? 0) + totalTaxaCartao;
264	    // total_pago tem que incluir a taxa de cada pagamento — ela já foi cobrada do
265	    // cliente junto com o valor base. Somar só p.valor (sem a taxa) fazia o saldo
266	    // devedor contar a taxa já paga como se ainda estivesse em aberto, cobrando ela
267	    // de novo no fechamento.
268	    const totalPago = (pagamentos ?? []).reduce((acc: number, p: any) => acc + p.valor + (p.taxa_cartao_valor ?? 0), 0);
269	
270	    return {
271	      subtotal: parseFloat(subtotal.toFixed(2)),
272	      total: parseFloat(totalFinal.toFixed(2)),
273	      total_pago: parseFloat(totalPago.toFixed(2)),
274	      saldo: parseFloat((totalFinal - totalPago).toFixed(2)),
275	    };
276	  }
277	
278	  // Lança uma saída automática no caixa aberto do restaurante — usado pra registrar troco
279	  // dado e gorjeta paga em dinheiro, sem o caixa precisar lançar isso manualmente depois.
280	  // `meio` default 'dinheiro' — troco devolvido via Pix (ver `troco_via_pix`) lança aqui
281	  // com meio 'pix' pra não entrar na conta de espécie física (ver `saldoEspecieDisponivel`).
282	  async registrarSaidaCaixa(restaurantId: number, descricao: string, valor: number, tipo: 'troco' | 'troco_pix' | 'gorjeta' | 'estorno_pagamento', meio: 'dinheiro' | 'pix' = 'dinheiro') {
283	    if (!(valor > 0)) return;
284	    const { data: caixa } = await this.supabase.client
285	      .from('caixas')
286	      .select('id, saidas')
287	      .eq('restaurant_id', restaurantId)
288	      .eq('status', 'aberto')
289	      .maybeSingle();
290	    if (!caixa) return; // sem caixa aberto: melhor não travar o pagamento por isso
291	
292	    const saidas = (caixa.saidas ?? []) as any[];
293	    const nova = { descricao, valor, meio, tipo, criado_em: new Date().toISOString() };
294	    await this.supabase.client.from('caixas').update({ saidas: [...saidas, nova] }).eq('id', caixa.id);
295	  }
296	
297	  // Lança uma entrada automática no caixa aberto — usado pra registrar o dinheiro que o
298	  // cliente entregou de fato numa venda em espécie (não o valor da venda, o valor recebido).
299	  async registrarEntradaCaixa(restaurantId: number, descricao: string, valor: number, tipo: string, meio: 'dinheiro' | 'pix' = 'dinheiro') {
300	    if (!(valor > 0)) return;
301	    const { data: caixa } = await this.supabase.client
302	      .from('caixas')
303	      .select('id, entradas')
304	      .eq('restaurant_id', restaurantId)
305	      .eq('status', 'aberto')
306	      .maybeSingle();
307	    if (!caixa) return;
308	
309	    const entradas = (caixa.entradas ?? []) as any[];
310	    const nova = { descricao, valor, meio, tipo, criado_em: new Date().toISOString() };
311	    await this.supabase.client.from('caixas').update({ entradas: [...entradas, nova] }).eq('id', caixa.id);
312	  }
313	
314	  // Deletar (ou trocar a forma de) um pagamento em dinheiro já lançado não desfazia
315	  // sozinho o que aconteceu no caixa físico: nem a entrada (valor_recebido — ver
316	  // registrarEntradaCaixa) nem a saída de troco que ela gerou (ver registrarSaidaCaixa).
317	  // Corrigir um valor errado sem estornar os dois deixava dinheiro fantasma — e faltando
318	  // o troco de volta, o saldo ficava errado pro lado contrário (faltando dinheiro).
319	  async estornarPagamentoEmDinheiro(
320	    restaurantId: number,
321	    identificador: string,
322	    pagamento: { forma_pagamento: string; valor: number; valor_recebido?: number | null; troco?: number | null; troco_via_pix?: boolean | null },
323	  ) {
324	    if (pagamento.forma_pagamento !== 'cash') return;
325	    const valorCreditado = pagamento.valor_recebido ?? pagamento.valor;
326	    await this.registrarSaidaCaixa(restaurantId, `Estorno pagamento removido - ${identificador}`, valorCreditado, 'estorno_pagamento');
327	    if ((pagamento.troco ?? 0) > 0) {
328	      // Troco devolvido via Pix nunca saiu da espécie física — o estorno credita de volta
329	      // no mesmo meio que saiu, senão "inventa" dinheiro que nunca existiu no caixa físico.
330	      const meio = pagamento.troco_via_pix ? 'pix' : 'dinheiro';
331	      await this.registrarEntradaCaixa(restaurantId, `Estorno troco (pagamento removido) - ${identificador}`, pagamento.troco as number, 'estorno_troco', meio);
332	    }
333	  }
334	
335	  // Comanda cancelada/excluída não pode deixar pra trás nenhum pagamento em dinheiro já
336	  // lançado no caixa físico — senão o dinheiro de uma venda que não existe mais continua
337	  // contando (mesmo problema do estorno individual, só que a comanda inteira some).
338	  async estornarPagamentosDaComanda(restaurantId: number, comandaId: number, identificador: string) {
339	    const { data: pagamentos } = await this.supabase.client
340	      .from('comanda_pagamentos')
341	      .select('forma_pagamento, valor, valor_recebido, troco, troco_via_pix')
342	      .eq('order_id', comandaId);
343	    for (const pagamento of (pagamentos ?? []) as any[]) {
344	      await this.estornarPagamentoEmDinheiro(restaurantId, identificador, pagamento);
345	    }
346	  }
347	
348	  // Espécie disponível agora no caixa aberto — soma direto do ledger (fundo + entradas em
349	  // dinheiro − saídas em dinheiro), sem precisar reconsultar pedidos. Usado pra bloquear
350	  // troco ou sangria sem fundo suficiente.
351	  async saldoEspecieDisponivel(restaurantId: number): Promise<number> {
352	    const { data: caixa } = await this.supabase.client
353	      .from('caixas')
354	      .select('valor_inicial, entradas, saidas')
355	      .eq('restaurant_id', restaurantId)
356	      .eq('status', 'aberto')
357	      .maybeSingle();
358	    if (!caixa) return 0;
359	    const emDinheiro = (arr: any[]) => ((arr ?? []) as any[])
360	      .filter((x) => !x.meio || x.meio === 'dinheiro')
361	      .reduce((s: number, x: any) => s + (x.valor ?? 0), 0);
362	    const saldo = (caixa.valor_inicial ?? 0) + emDinheiro(caixa.entradas) - emDinheiro(caixa.saidas);
363	    return parseFloat(saldo.toFixed(2));
364	  }
