366	  // Registra um pagamento parcial — não fecha a comanda sozinho, só abate do saldo devedor.
367	  // Chamado tanto pelo garçom (informar forma de pagamento) quanto pelo caixa (conferência).
368	  // Em dinheiro, valorRecebido é o que o cliente entregou — troco é calculado e vira saída
369	  // automática no caixa (ver registrarSaidaCaixa).
370	  async registrarPagamento(
371	    comandaId: number,
372	    origem: 'garcom' | 'estabelecimento',
373	    valor: number,
374	    formaPagamento: string,
375	    restaurantId: number,
376	    valorRecebido?: number,
377	    identificador?: string,
378	    taxaCartaoValor?: number,
379	    trocoViaPix = false,
380	  ) {
381	    if (!valor || valor <= 0) throw new BadRequestException('Valor precisa ser maior que zero');
382	    if (!formaPagamento) throw new BadRequestException('Informe a forma de pagamento');
383	
384	    let troco: number | null = null;
385	    if (formaPagamento === 'cash' && valorRecebido !== undefined) {
386	      if (valorRecebido < valor) throw new BadRequestException('Valor recebido não pode ser menor que o valor a pagar');
387	      troco = parseFloat((valorRecebido - valor).toFixed(2));
388	      // Troco via Pix não sai da espécie física do caixa — não precisa checar fundo.
389	      if (troco > 0 && !trocoViaPix) {
390	        const saldoEspecie = await this.saldoEspecieDisponivel(restaurantId);
391	        if (saldoEspecie < troco) {
392	          throw new BadRequestException(
393	            `Caixa não tem troco suficiente em espécie (disponível: R$ ${saldoEspecie.toFixed(2)}, necessário: R$ ${troco.toFixed(2)}). Registre uma Adição no caixa antes de finalizar esse pagamento, ou marque "Troco via Pix".`,
394	          );
395	        }
396	      }
397	    }
398	
399	    const { error } = await this.supabase.client
400	      .from('comanda_pagamentos')
401	      .insert({
402	        order_id: comandaId, valor, forma_pagamento: formaPagamento, origem,
403	        valor_recebido: valorRecebido ?? null, troco, taxa_cartao_valor: taxaCartaoValor || null,
404	        troco_via_pix: !!(troco && troco > 0 && trocoViaPix),
405	      });
406	    if (error) throw error;
407	
408	    if (formaPagamento === 'cash' && valorRecebido !== undefined) {
409	      await this.registrarEntradaCaixa(restaurantId, `Venda em dinheiro${identificador ? ` - ${identificador}` : ''}`, valorRecebido, 'venda_dinheiro');
410	      if (troco && troco > 0) {
411	        if (trocoViaPix) {
412	          await this.registrarSaidaCaixa(restaurantId, `Troco via Pix${identificador ? ` - ${identificador}` : ''}`, troco, 'troco_pix', 'pix');
413	        } else {
414	          await this.registrarSaidaCaixa(restaurantId, `Troco${identificador ? ` - ${identificador}` : ''}`, troco, 'troco');
415	        }
416	      }
417	    }
418	
419	    return this.saldoDevedor(comandaId);
420	  }
