422	  // Permissão default true (opt-out) — preserva o comportamento de quem já usava
423	  // isso sem restrição antes da permissão existir; dono desativa por garçom se quiser.
424	  async registrarPagamentoComoGarcom(comandaId: number, garcomId: number, valor: number, formaPagamento: string, podePagamentoParcial = true, valorRecebido?: number, trocoViaPix = false) {
425	    if (!podePagamentoParcial) throw new ForbiddenException('Você não tem permissão para registrar pagamento parcial');
426	    const comanda = await this.garantirComandaDoGarcom(comandaId, garcomId);
427	    if (!['aberta', 'fechada_garcom'].includes(comanda.status)) {
428	      throw new BadRequestException('Comanda já foi paga ou cancelada');
429	    }
430	    const identificador = `Comanda #${comanda.numero_comanda ?? comandaId}`;
431	    const taxaCartaoValor = await this.calcularTaxaCartao(comanda.restaurant_id, valor, formaPagamento);
432	    return this.registrarPagamento(comandaId, 'garcom', valor, formaPagamento, comanda.restaurant_id, valorRecebido, identificador, taxaCartaoValor, trocoViaPix);
433	  }
