435	  private async buscarPagamentoDoGarcom(comandaId: number, pagamentoId: number) {
436	    const { data } = await this.supabase.client
437	      .from('comanda_pagamentos')
438	      .select('id, origem, forma_pagamento, valor, valor_recebido, troco, troco_via_pix')
439	      .eq('id', pagamentoId)
440	      .eq('order_id', comandaId)
441	      .maybeSingle();
442	    if (!data) throw new NotFoundException('Pagamento não encontrado');
443	    // Garçom só edita/remove o que ele mesmo lançou — pagamento do caixa é exclusivo do PDV.
444	    if (data.origem !== 'garcom') throw new ForbiddenException('Só é possível editar/remover pagamentos lançados por você');
445	    return data;
