449	    comandaId: number, garcomId: number, pagamentoId: number, valor: number, formaPagamento: string, podePagamentoParcial = true,
450	  ) {
451	    if (!podePagamentoParcial) throw new ForbiddenException('Você não tem permissão para registrar pagamento parcial');
452	    const comanda = await this.garantirComandaDoGarcom(comandaId, garcomId);
