509	  async abrirComanda(garcomId: number, restaurantId: number, body: AbrirComandaBody, restauranteAberto?: boolean, salaoModo: 'mesas' | 'comandas' | 'ambos' = 'ambos') {
510	    if (!restauranteAberto) {
511	      throw new ForbiddenException('Restaurante fechado — não é possível abrir mesa/comanda');
512	    }
513	    if (salaoModo === 'mesas' && !body.mesa_id) {
514	      throw new BadRequestException('Este restaurante só trabalha com mesas — selecione uma mesa');
515	    }
516	    if (salaoModo === 'comandas' && body.mesa_id) {
517	      throw new BadRequestException('Este restaurante só trabalha com comandas avulsas — não vincule a uma mesa');
518	    }
519	    if (!body.cliente_nome || !body.cliente_telefone) {
520	      throw new BadRequestException('Nome e telefone do cliente são obrigatórios');
521	    }
522	
523	    // Primeira comanda do garçom abre a sessão de trabalho dele automaticamente — sem
524	    // ação nenhuma do lado dele. Não bloqueia nem interfere na abertura da comanda em si.
525	    await this.garcomTurno.garantirTurnoAberto(garcomId, restaurantId);
526	
527	    let mesa: { id: number } | null = null;
528	    if (body.mesa_id) {
529	      const { data } = await this.supabase.client
530	        .from('mesas')
531	        .select('id, status')
532	        .eq('id', body.mesa_id)
533	        .eq('restaurant_id', restaurantId)
534	        .maybeSingle();
535	      if (!data) throw new NotFoundException('Mesa não encontrada');
536	      if (data.status !== 'livre') throw new BadRequestException('Mesa não está livre');
537	      mesa = data;
538	    }
539	
540	    const { data: caixaAberto } = await this.supabase.client
541	      .from('caixas')
542	      .select('id')
543	      .eq('restaurant_id', restaurantId)
544	      .eq('status', 'aberto')
545	      .maybeSingle();
546	
547	    // Numeração sequencial por dia — só pra identificação fácil ("comanda 3"), reinicia
548	    // a cada dia. Não precisa ser à prova de corrida (volume baixo de comandas simultâneas).
549	    const inicioDoDia = new Date();
550	    inicioDoDia.setHours(0, 0, 0, 0);
551	    const { count } = await this.supabase.client
552	      .from('orders')
553	      .select('id', { count: 'exact', head: true })
554	      .eq('restaurant_id', restaurantId)
555	      .eq('canal', 'presencial')
556	      .gte('created_at', inicioDoDia.toISOString());
557	    const numeroComanda = (count ?? 0) + 1;
558	
559	    const customerId = await this.resolverOuCriarClienteComanda(restaurantId, body.cliente_nome, body.cliente_telefone);
560	
561	    const { data: comanda, error } = await this.supabase.client
562	      .from('orders')
563	      .insert({
564	        restaurant_id: restaurantId,
565	        canal: 'presencial',
566	        status: 'aberta',
567	        garcom_id: garcomId,
568	        mesa_id: mesa?.id ?? null,
569	        customer_id: customerId,
570	        cliente_mesa_nome: body.cliente_nome,
571	        cliente_mesa_telefone: body.cliente_telefone,
572	        total: 0,
573	        caixa_id: caixaAberto?.id ?? null,
574	        numero_comanda: numeroComanda,
575	      })
576	      .select()
577	      .single();
578	    if (error) throw error;
579	
580	    if (mesa) {
581	      await this.supabase.client.from('mesas').update({ status: 'ocupada' }).eq('id', mesa.id);
582	    }
583	
584	    return comanda;
585	  }
