587	  async minhasComandas(garcomId: number) {
588	    const CAMPOS = 'id, mesa_id, cliente_mesa_nome, cliente_mesa_telefone, status, total, numero_comanda, created_at, conferencia_solicitada_em, conferencia_vista_garcom_em, ultimo_pedido_cliente_em';
589	    const { data, error } = await this.supabase.client
590	      .from('orders')
591	      .select(CAMPOS)
592	      .eq('garcom_id', garcomId)
593	      .eq('canal', 'presencial')
594	      .in('status', ['aberta', 'fechada_garcom'])
595	      .order('created_at', { ascending: false });
596	    if (error) throw error;
597	
598	    // Comanda já paga mas com item ainda não entregue continua na lista — cliente pode
599	    // pagar adiantado e só receber o prato depois (ver `pagar`), então o garçom não pode
600	    // perder de vista o que ainda falta levar só porque o caixa já cobrou.
601	    const { data: itensPendentes } = await this.supabase.client
602	      .from('order_items')
603	      .select(`order_id, orders!inner(${CAMPOS}, garcom_id, canal)`)
604	      .eq('orders.garcom_id', garcomId)
605	      .eq('orders.canal', 'presencial')
606	      .eq('orders.status', 'paga')
607	      .in('status', ['preparando', 'pronto'])
608	      .eq('entregue_garcom', false);
609	
610	    const pagasComPendencia = new Map<number, any>();
611	    for (const i of (itensPendentes ?? []) as any[]) {
612	      if (i.orders && !pagasComPendencia.has(i.orders.id)) pagasComPendencia.set(i.orders.id, i.orders);
613	    }
614	
615	    return [...(data ?? []), ...pagasComPendencia.values()];
616	  }
