618	  // Itens prontos pra buscar, desse garçom — o portal dele faz polling nisso pra tocar
619	  // o alarme sonoro (ver useNotificacaoSonora no front). Não filtra por status da
620	  // comanda (aberta/fechada_garcom/paga) de propósito: cliente pode pagar adiantado e
621	  // só receber o prato depois (ver `pagar`, que não exige entrega confirmada pra
622	  // fechar) — o alerta tem que continuar tocando até o garçom confirmar a entrega,
623	  // mesmo com a comanda já paga.
624	  async itensProntos(garcomId: number) {
625	    const { data: itens } = await this.supabase.client
626	      .from('order_items')
627	      .select('id, order_id, quantity, products(name), orders!inner(garcom_id, canal, numero_comanda, mesa_id, cliente_mesa_nome, mesas(numero, nome))')
628	      .eq('orders.garcom_id', garcomId)
629	      .eq('orders.canal', 'presencial')
630	      .eq('status', 'pronto')
631	      .eq('entregue_garcom', false);
632	
633	    return (itens ?? []).map((i: any) => ({
634	      item_id: i.id,
635	      order_id: i.order_id,
636	      numero_comanda: i.orders?.numero_comanda ?? i.order_id,
637	      mesa: i.orders?.mesas ? `Mesa ${i.orders.mesas.numero}${i.orders.mesas.nome ? ' - ' + i.orders.mesas.nome : ''}` : null,
638	      cliente: i.orders?.cliente_mesa_nome ?? null,
639	      product_name: i.products?.name,
640	      quantity: i.quantity,
641	    }));
642	  }
