644	  // Fila de preparo do restaurante inteiro (não só as comandas do garçom logado) — o
645	  // garçom usa isso pra responder ao cliente presencial "quantos faltam antes do meu"
646	  // e "quanto tempo em média demora", sem precisar ir até a cozinha.
647	  async filaCozinha(restaurantId: number) {
648	    const { data: itensRaw, error } = await this.supabase.client
649	      .from('order_items')
650	      .select('id, order_id, quantity, status, enviado_em, preparando_em, products(name), orders!inner(restaurant_id, canal, status, numero_comanda, cliente_mesa_nome, mesas(numero, nome))')
651	      .eq('orders.restaurant_id', restaurantId)
652	      .eq('orders.canal', 'presencial')
653	      .in('orders.status', ['aberta', 'fechada_garcom'])
654	      .in('status', ['enviado', 'preparando'])
655	      .order('enviado_em', { ascending: true });
656	    if (error) throw error;
657	
658	    const itens = (itensRaw ?? []).map((i: any) => ({
659	      item_id: i.id,
660	      order_id: i.order_id,
661	      numero_comanda: i.orders?.numero_comanda ?? i.order_id,
662	      mesa: i.orders?.mesas ? `Mesa ${i.orders.mesas.numero}${i.orders.mesas.nome ? ' - ' + i.orders.mesas.nome : ''}` : null,
663	      cliente_mesa_nome: i.orders?.cliente_mesa_nome ?? null,
664	      product_name: i.products?.name,
665	      quantity: i.quantity,
666	      status: i.status,
667	      enviado_em: i.enviado_em,
668	      preparando_em: i.preparando_em,
669	    }));
670	
671	    // Três médias, sobre itens finalizados hoje: espera (na fila, antes do preparo
672	    // começar), preparo (tempo ativo de cozinha) e geral (soma das duas, o que o
673	    // cliente sente desde que pediu até ficar pronto).
674	    const inicioHoje = new Date();
675	    inicioHoje.setHours(0, 0, 0, 0);
676	    const { data: prontosHoje } = await this.supabase.client
677	      .from('order_items')
678	      .select('enviado_em, preparando_em, pronto_em, orders!inner(restaurant_id, canal)')
679	      .eq('orders.restaurant_id', restaurantId)
680	      .eq('orders.canal', 'presencial')
681	      .eq('status', 'pronto')
682	      .not('enviado_em', 'is', null)
683	      .not('preparando_em', 'is', null)
684	      .not('pronto_em', 'is', null)
685	      .gte('pronto_em', inicioHoje.toISOString())
686	      // Pedido enviado em dia anterior (ficou preso/esquecido) e só marcado pronto hoje
687	      // não é preparo "de hoje" — entraria como outlier gigante e mentiria a média.
688	      .gte('enviado_em', inicioHoje.toISOString());
689	
690	    const media = (segundos: number[]) =>
691	      segundos.length ? Math.round(segundos.reduce((soma, s) => soma + s, 0) / segundos.length) : null;
692	
693	    const esperas = (prontosHoje ?? []).map(
694	      (p: any) => (new Date(p.preparando_em).getTime() - new Date(p.enviado_em).getTime()) / 1000,
695	    );
696	    const preparos = (prontosHoje ?? []).map(
697	      (p: any) => (new Date(p.pronto_em).getTime() - new Date(p.preparando_em).getTime()) / 1000,
698	    );
699	    const gerais = (prontosHoje ?? []).map(
700	      (p: any) => (new Date(p.pronto_em).getTime() - new Date(p.enviado_em).getTime()) / 1000,
701	    );
702	
703	    return {
704	      itens,
705	      tempoMedioEsperaSegundos: media(esperas),
706	      tempoMedioPreparoSegundos: media(preparos),
707	      tempoMedioGeralSegundos: media(gerais),
708	      amostras: (prontosHoje ?? []).length,
709	    };
710	  }
