712	  async obterComanda(comandaId: number, garcomId: number) {
713	    const comanda = await this.garantirComandaDoGarcom(comandaId, garcomId);
714	
715	    const { data: itens, error } = await this.supabase.client
716	      .from('order_items')
717	      .select('id, product_id, quantity, unit_price, observacao, combo_nome, combo_quantidade, status, enviado_em, entregue_garcom, products(name, image_url)')
718	      .eq('order_id', comandaId)
719	      .order('id', { ascending: true });
720	    if (error) throw error;
721	
722	    const { data: pagamentos } = await this.supabase.client
723	      .from('comanda_pagamentos')
724	      .select('id, valor, forma_pagamento, origem, criado_em, taxa_cartao_valor, valor_recebido, troco, troco_via_pix')
725	      .eq('order_id', comandaId)
726	      .order('criado_em', { ascending: true });
727	    const saldo = await this.saldoDevedor(comandaId);
728	
729	    // Sugestão de gorjeta exibida pro garçom/cliente antes do fechamento — informativa,
730	    // o valor de fato lançado é o que o caixa confirma no PDV (pode ajustar).
731	    const { data: restaurante } = await this.supabase.client
732	      .from('restaurants')
733	      .select('gorjeta_percentual, taxa_cartao_percentual')
734	      .eq('id', comanda.restaurant_id)
735	      .maybeSingle();
736	    const percentual = restaurante?.gorjeta_percentual ?? 0;
737	    const subtotalItens = (itens ?? []).reduce((acc: number, i: any) => acc + i.quantity * i.unit_price, 0);
738	    const gorjeta_sugestao = { percentual, valor_sugerido: parseFloat(((subtotalItens * percentual) / 100).toFixed(2)) };
739	    const taxa_cartao_percentual = restaurante?.taxa_cartao_percentual ?? 0;
740	
741	    return { ...comanda, itens, pagamentos: pagamentos ?? [], saldo, gorjeta_sugestao, taxa_cartao_percentual };
742	  }
