744	  async adicionarItens(comandaId: number, garcomId: number, itens: ItemComandaBody[]) {
745	    if (!itens?.length) throw new BadRequestException('Informe ao menos 1 item');
746	
747	    const comanda = await this.garantirComandaDoGarcom(comandaId, garcomId);
748	    if (comanda.status !== 'aberta') throw new BadRequestException('Comanda não está aberta');
749	
750	    const itensDiretos = itens.filter((i) => i.product_id != null);
751	    const itensCombo = itens.filter((i) => i.combo_id != null);
752	
753	    const prodIds = itensDiretos.map((i) => i.product_id as number);
754	    const { data: produtos, error: errProd } = await this.supabase.client
755	      .from('products')
756	      .select('id, price, is_active')
757	      .in('id', prodIds.length ? prodIds : [0]);
758	    if (errProd) throw errProd;
759	
760	    const prodMap = Object.fromEntries((produtos ?? []).map((p) => [p.id, p]));
761	    for (const item of itensDiretos) {
762	      const prod = prodMap[item.product_id as number];
763	      if (!prod) throw new BadRequestException(`Produto ${item.product_id} não encontrado`);
764	      if (!prod.is_active) throw new BadRequestException(`Produto ${item.product_id} inativo`);
765	    }
766	
767	    // Combo explode nas linhas dos produtos reais (mesma observação copiada pra cada
768	    // linha, já que não faz sentido dividir a nota do garçom entre os itens do combo).
769	    const linhasCombo = (
770	      await Promise.all(
771	        itensCombo.map(async (i) => {
772	          const linhas = await this.combosService.expandir(i.combo_id as number, i.quantity, comanda.restaurant_id);
773	          return linhas.map((l) => ({ ...l, observacao: i.observacao }));
774	        }),
775	      )
776	    ).flat();
777	
778	    const linhasDiretas: (ItemExpandido & { observacao?: string })[] = itensDiretos.map((i) => ({
779	      product_id: i.product_id as number,
