      <option value="debit_card">Cartão de débito</option>
      <option value="cash">Dinheiro</option>
    </select>
  </div>
  )}
  {podeEditar && taxaCartaoValorParcial > 0 && (
    <p className="text-[11px] text-[#FF441F] font-medium">
