1	import { BadRequestException, Injectable, NotFoundException } from '@nestjs/common';
2	import { SupabaseService } from '../supabase/supabase.service';
3	import { SalaoService } from './salao.service';
4	import type { ItemComandaBody } from './salao.service';
5	import { EstoqueService } from '../estoque/estoque.service';
6	import { CombosService, ItemExpandido } from '../combos/combos.service';
7	
8	// PDV do caixa (lado estabelecimento): ações de cancelar/desconto/acréscimo/pagar
9	// são exclusivas do dono (RestaurantOwnerGuard) — o garçom nunca tem acesso a
10	// essas rotas (ver salao.controller.ts, que só cobre abrir/adicionar/enviar/fechar).
11	@Injectable()
12	export class SalaoPdvService {
13	  constructor(
14	    private supabase: SupabaseService,
15	    private salaoService: SalaoService,
16	    private estoque: EstoqueService,
17	    private combos: CombosService,
18	  ) {}
19	
20	  async mesas(restaurantId: number) {
21	    const { data: mesas, error } = await this.supabase.client
22	      .from('mesas')
23	      .select('id, numero, nome, status, auto_atendimento_token')
24	      .eq('restaurant_id', restaurantId)
25	      .order('numero', { ascending: true });
26	    if (error) throw error;
27	
28	    const { data: comandas } = await this.supabase.client
29	      .from('orders')
30	      .select('id, mesa_id, garcom_id, total, status, numero_comanda, cliente_mesa_nome, garcons(nome), aberto_por_nome, conferencia_solicitada_em')
31	      .eq('restaurant_id', restaurantId)
32	      .eq('canal', 'presencial')
33	      .in('status', ['aberta', 'fechada_garcom'])
34	      .not('mesa_id', 'is', null);
35	
36	    const comandaPorMesa = new Map((comandas ?? []).map((c: any) => [c.mesa_id, c]));
37	
38	    return (mesas ?? []).map((m: any) => ({ ...m, comanda: comandaPorMesa.get(m.id) ?? null }));
39	  }
40	
41	  // Bloqueia uma mesa livre (reserva, manutenção...) — fica indisponível pro garçom
42	  // até ser desbloqueada, sem precisar de comanda aberta nela.
43	  async bloquearMesa(mesaId: number, restaurantId: number) {
44	    const { data: mesa } = await this.supabase.client
45	      .from('mesas').select('id, status').eq('id', mesaId).eq('restaurant_id', restaurantId).maybeSingle();
46	    if (!mesa) throw new NotFoundException('Mesa não encontrada');
47	    if (mesa.status !== 'livre') throw new BadRequestException('Só é possível bloquear uma mesa livre');
48	
49	    const { error } = await this.supabase.client.from('mesas').update({ status: 'bloqueada' }).eq('id', mesaId);
50	    if (error) throw error;
51	    return { ok: true };
52	  }
53	
54	  async desbloquearMesa(mesaId: number, restaurantId: number) {
55	    const { data: mesa } = await this.supabase.client
56	      .from('mesas').select('id, status').eq('id', mesaId).eq('restaurant_id', restaurantId).maybeSingle();
57	    if (!mesa) throw new NotFoundException('Mesa não encontrada');
58	    if (mesa.status !== 'bloqueada') throw new BadRequestException('Mesa não está bloqueada');
59	
60	    const { error } = await this.supabase.client.from('mesas').update({ status: 'livre' }).eq('id', mesaId);
61	    if (error) throw error;
62	    return { ok: true };
63	  }
64	
65	  // Estabelecimento abre mesa/comanda direto (sem garçom envolvido) — mesma regra de
66	  // salao_modo e obrigatoriedade de nome/telefone do cliente do lado do garçom.
67	  // Guarda o primeiro nome de quem tava logado (aberto_por_nome) pro card da mesa
68	  // mostrar "Caixa: nome" pro garçom e pro próprio estabelecimento.
